185	    const zipPath = path.join(dir, "Hack.zip");
186	
187	    if (fs.existsSync(zipPath)) {
188	      console.log(`Extracting HackNerdFont-Regular.ttf from cached ${zipPath}`);
189	      const zipBuf = fs.readFileSync(zipPath);
190	      const ttf = extractZipEntry(zipBuf, "HackNerdFont-Regular.ttf");
191	      fs.writeFileSync(FONT_PATH, ttf);
192	      return;
193	    }
194	  }
