217	function readPngDimensions(pngPath) {
218	  const buf = fs.readFileSync(pngPath);
219	  // IHDR is the first chunk in a well-formed PNG: 8-byte signature, 4-byte
220	  // length, 4-byte "IHDR", then width/height as big-endian uint32s.
221	  return { width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
222	}
223	
224	// Renders svgMarkup inside a headless page whose viewport (at
225	// DEVICE_SCALE_FACTOR) targets targetWidth x targetHeight device pixels —
226	// the reference PNG's own dimensions — so the SVG's vector content is
227	// rescaled by the browser itself (crisp) rather than by resampling a raster
228	// afterwards. The SVG keeps its own viewBox, so content scales
229	// proportionally to fill the forced box.
230	async function rasterizeSVG(browser, svgMarkup, fontBase64, targetWidth, targetHeight) {
231	  const cssWidth = Math.max(1, Math.round(targetWidth / DEVICE_SCALE_FACTOR));
232	  const cssHeight = Math.max(1, Math.round(targetHeight / DEVICE_SCALE_FACTOR));
233	
234	  // The exporter's <svg> carries no preserveAspectRatio, so it defaults to
235	  // "xMidYMid meet": the browser would scale the viewBox uniformly to fit
236	  // inside the CSS box forced below and letterbox/center it, rather than
237	  // filling that box — which silently reintroduces a spatial offset between
238	  // the two rasters (content shifted down/right by the letterboxing gap)
239	  // that swamped the diff with edge noise before this fix. "none" makes the
240	  // two axes scale independently, actually filling cssWidth x cssHeight.
241	  svgMarkup = svgMarkup.replace("<svg ", '<svg preserveAspectRatio="none" ');
242	
243	  const context = await browser.newContext({
244	    viewport: { width: cssWidth, height: cssHeight },
245	    deviceScaleFactor: DEVICE_SCALE_FACTOR,
246	  });
247	
248	  const page = await context.newPage();
249	
250	  const html = `<!doctype html>
251	<html>
252	<head>
253	<meta charset="utf-8">
254	<style>
255	  @font-face {
256	    font-family: "${FONT_FAMILY}";
257	    src: url(data:font/ttf;base64,${fontBase64}) format("truetype");
258	    font-weight: normal;
259	    font-style: normal;
260	  }
261	  html, body { margin: 0; padding: 0; background: transparent; }
262	  /* Force the SVG's rendered box to exactly the viewport (which
263	     DEVICE_SCALE_FACTOR then rasterizes to targetWidth x targetHeight); the
264	     viewBox the exporter already wrote keeps the content proportional. */
265	  svg { display: block; width: 100vw; height: 100vh; }
266	</style>
267	</head>
268	<body>${svgMarkup}</body>
269	</html>`;
270	
271	  await page.setContent(html, { waitUntil: "networkidle" });
272	  await page.evaluate(() => document.fonts.ready);
273	  // One extra frame so the webfont swap (FOUT) has actually repainted
274	  // before the screenshot — document.fonts.ready resolves once the font is
275	  // *loaded*, not once the page has repainted with it.
276	  await page.waitForTimeout(50);
277	
278	  // omitBackground: true keeps the page's transparent regions transparent
279	  // in the captured PNG (alpha 0) instead of flattening them onto opaque
280	  // white. The reference PNG's own canvas outside the window+shadow is
281	  // genuinely transparent (image.go's gg context starts fully transparent
282	  // and is never filled) — matching that, rather than defaulting to white,
283	  // is what makes the outer margin diff meaningfully instead of reporting
284	  // "100% different" on every pixel of it.
285	  const buf = await page.screenshot({ omitBackground: true });
286	  await context.close();
287	
288	  return buf;
289	}
290	
291	// Pads the smaller of two RGBA buffers (top-left anchored) so both share the
292	// same width/height. The two rasters only ever differ by a few px of
293	// rounding slop (see rasterizeSVG's cssWidth/cssHeight rounding) once the
294	// SVG has already been forced to the PNG's own target dimensions, so a
295	// transparent-black pad — rather than scaling either image again, or
296	// cropping content away — is the least lossy way to reconcile that residual
297	// slop before a pixel-for-pixel diff.
298	function padToCommonSize(a, b) {
299	  const width = Math.max(a.width, b.width);
300	  const height = Math.max(a.height, b.height);
301	
302	  const pad = (img) => {
303	    if (img.width === width && img.height === height) {
304	      return img.data;
305	    }
306	
307	    const buf = Buffer.alloc(width * height * 4, 0);
308	
309	    for (let y = 0; y < img.height; y++) {
310	      img.data.copy(buf, y * width * 4, y * img.width * 4, (y * img.width + img.width) * 4);
311	    }
312	
313	    return buf;
314	  };
315	
316	  return { aData: pad(a), bData: pad(b), width, height };
317	}
318	
319	async function processTheme(theme, ctx) {
320	  const configPath = path.join(THEMES_DIR, `${theme}.omp.json`);
321	
322	  if (!fs.existsSync(configPath)) {
323	    throw new Error(`theme not found: ${configPath}`);
324	  }
325	
326	  const pngPath = path.join(OUT_DIR, `${theme}.png`);
327	  const svgPath = path.join(OUT_DIR, `${theme}.svg`);
328	  const rasterPath = path.join(OUT_DIR, `${theme}.raster.png`);
329	  const diffPath = path.join(OUT_DIR, `${theme}.diff.png`);
330	
331	  run(ctx.oldBin, [
332	    "config",
333	    "export",
334	    "image",
335	    "--config",
336	    configPath,
337	    "--data",
338	    DATA_FIXTURE,
339	    "--format",
340	    "png",
341	    "-o",
342	    pngPath,
343	  ]);
344	
345	  run(ctx.newBin, [
346	    "config",
347	    "export",
348	    "image",
349	    "--config",
350	    configPath,
351	    "--data",
352	    DATA_FIXTURE,
353	    "--font-family",
354	    FONT_FAMILY,
355	    "-o",
356	    svgPath,
357	  ]);
358	
359	  const { width: pngWidth, height: pngHeight } = readPngDimensions(pngPath);
360	  const svgMarkup = fs.readFileSync(svgPath, "utf8");
361	
362	  const rasterBuf = await rasterizeSVG(ctx.browser, svgMarkup, ctx.fontBase64, pngWidth, pngHeight);
363	  fs.writeFileSync(rasterPath, rasterBuf);
364	
365	  const png = PNG.sync.read(fs.readFileSync(pngPath));
366	  const raster = PNG.sync.read(rasterBuf);
367	
368	  const dimensionsMatched = png.width === raster.width && png.height === raster.height;
369	  const { aData, bData, width, height } = padToCommonSize(png, raster);
370	
371	  const diff = new PNG({ width, height });
