//
// Usage:
//
//	rgb := HexToRgb("ccc") // rgb: [204 204 204]
//	rgb := HexToRgb("aabbcc") // rgb: [170 187 204]
//	rgb := HexToRgb("#aabbcc") // rgb: [170 187 204]
//	rgb := HexToRgb("0xad99c0") // rgb: [170 187 204]
func HexToRgb(hex string) (rgb []int) {
	hex = strings.TrimSpace(hex)
	if hex == "" {
		return
	}

	// like from css. eg "#ccc" "#ad99c0"
