func (segment *Segment) restoreData() bool {
	dataOnly := segment.env.Flags().DataOnly

	raw, OK := segment.env.Flags().SegmentData[segment.DataKey()]
	if !OK {
		if !dataOnly {
			return false
		}

		// Nothing recorded under this key, and probing is not allowed: the
		// segment renders as absent rather than as itself. Falling through
		// here is what made a "hermetic" replay quietly reach the network -
		// a key only has to miss for the segment to run for real, and
		// DataKey() is the alias when one is set, so a config that renames a
		// segment misses its own recorded entry.
		segment.Enabled = false
		segment.restored = true

		log.Debug("no recorded data and probing disallowed, suppressing segment: ", segment.Name())

		return true
	}

	recorded, isRecorded := decodeRecordedSegment(raw)
	if !isRecorded {
		if !dataOnly {
			segment.pendingData = raw
			return false
		}

		// A flat, hand-written entry would normally be overlaid on top of
		// live-derived state (see this function's doc comment). With probing
		// disallowed there is no live state to overlay onto, so the entry has
		// to stand on its own - which also means a partial one renders a
		// partial segment, since the fields Enabled() would have computed are
		// never computed. Record a deterministic file with
		// `oh-my-posh config export data` rather than hand-writing one when
		// rendering this way.
		if err := json.Unmarshal(raw, &segment.writer); err != nil {
			log.Error(err)

			segment.Enabled = false
			segment.restored = true

			return true
		}

		segment.Enabled = true
		segment.restored = true

		template.Cache.AddSegmentData(segment.Name(), segment.writer)

		log.Debug("restored segment from hand-written data: ", segment.Name())

		return true
	}

