// The gap DataOnly closes: without it, a segment the data file does not cover
// falls through to writer.Enabled() and probes the real machine, so a replay is
// only hermetic when every configured segment happens to be recorded. SESSION is
// used deliberately - its Enabled() calls Getenv and Platform, neither of which
// newDataReplayEnv stubs, so a fall-through panics rather than quietly passing.
func TestSegment_RestoreDataOnlyMissingKeySuppressesWithoutProbing(t *testing.T) {
	env := newDataReplayEnv(&runtime.Flags{DataOnly: true})

	segment := &Segment{Type: SESSION}
	segment.Execute(env)

	assert.False(t, segment.Enabled, "an uncovered segment renders as absent, not as itself")
	assert.True(t, segment.restored, "suppression counts as restored: no live probe happened")
}

// The realistic way a key misses even with a complete recording: DataKey() is
// the alias when one is set, so renaming a segment in the config walks away
// from its own recorded entry. Without DataOnly that silently becomes a live
// probe (see TestSegment_RestoreDataAliasBeatsType, which pins the same miss
// without it).
func TestSegment_RestoreDataOnlyAliasMissSuppressesWithoutProbing(t *testing.T) {
	flags := &runtime.Flags{
		DataOnly: true,
		SegmentData: map[string]json.RawMessage{
			"session": json.RawMessage(`{"enabled":true,"data":{"SSHSession":true}}`),
		},
	}
	env := newDataReplayEnv(flags)

	segment := &Segment{Type: SESSION, Alias: "mybox"}
	segment.Execute(env)

	assert.False(t, segment.Enabled, "the recorded type-keyed entry must not be used for an aliased segment")
	assert.True(t, segment.restored)
}

// A flat, hand-written entry is normally overlaid on top of live-derived state.
// With probing disallowed there is no live state to overlay onto, so it has to
// stand on its own - again proven by SESSION's unstubbed Getenv/Platform.
func TestSegment_RestoreDataOnlyFlatEntryAppliesWithoutProbing(t *testing.T) {
	flags := &runtime.Flags{
		DataOnly: true,
		SegmentData: map[string]json.RawMessage{
			"session": json.RawMessage(`{"SSHSession":true}`),
		},
	}
	env := newDataReplayEnv(flags)

	segment := &Segment{Type: SESSION}
	segment.Execute(env)

	assert.True(t, segment.Enabled)
	assert.True(t, segment.restored)

	writer, ok := segment.Writer().(*segments.Session)
	require.True(t, ok)
	assert.True(t, writer.SSHSession, "the hand-written entry stands on its own")
}

