// Screenshot the studio at desktop and narrow, light and dark, against the
// built site. Waits for the wasm module to actually render before shooting.
import { chromium } from "playwright";

const base = process.argv[2] || "http://localhost:3010";
const out = process.argv[3];

const browser = await chromium.launch();

for (const [label, width, height, scheme] of [
  ["light-desktop", 1280, 1000, "light"],
  ["dark-desktop", 1280, 1000, "dark"],
  ["light-narrow", 390, 900, "light"],
]) {
  const context = await browser.newContext({
    viewport: { width, height },
    colorScheme: scheme,
  });
  const page = await context.newPage();

  await page.goto(`${base}/studio`, { waitUntil: "networkidle" });

  // The prompt SVG only appears once the module has downloaded and rendered.
  await page.waitForSelector("svg.omp-window, svg", { timeout: 120000 }).catch(() => {});
  await page.waitForTimeout(1500);

  await page.screenshot({ path: `${out}/studio-${label}.png`, fullPage: false });
  console.log(label, "shot");

  await context.close();
}

await browser.close();

