"""WCAG contrast for the greys the two pages use for body text."""
import re
import sys


def luminance(hex_colour):
    r, g, b = (int(hex_colour[i:i + 2], 16) / 255 for i in (1, 3, 5))
    chan = [c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4 for c in (r, g, b)]
    return 0.2126 * chan[0] + 0.7152 * chan[1] + 0.0722 * chan[2]


def ratio(a, b):
    la, lb = luminance(a), luminance(b)
    hi, lo = max(la, lb), min(la, lb)
    return (hi + 0.05) / (lo + 0.05)


css = open(sys.argv[1], encoding="utf-8").read()
greys = {}
for name in ("gray-600", "gray-700", "gray-800", "gray-400"):
    m = re.search(r"--ifm-color-" + name + r":\s*(#[0-9a-fA-F]{6})", css)
    if m:
        greys[name] = m.group(1)

print("light mode, text on white (#ffffff) — AA body text needs 4.5:1\n")
for name, value in greys.items():
    r = ratio(value, "#ffffff")
    print(f"  {name:9} {value}  {r:5.2f}:1  {'PASS' if r >= 4.5 else 'FAIL'}")

